import {catalog} from './catalog.js';
export const cash=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
export function totalCost(item,tax=0){return Number(item.price||0)*(1+Number(tax||0)/100)+Number(item.delivery||0)+Number(item.assembly||0);}
export function fitCheck(item,space){const dims=[item.width,item.depth,item.height].map(Number);if(dims.some(n=>!Number.isFinite(n)||n<=0))return 'Add all three item dimensions';const [w,d]=[space.width,space.depth].map(Number);if(!w||!d)return 'Add room dimensions';const footprint=(dims[0]<=w&&dims[1]<=d)||(dims[1]<=w&&dims[0]<=d);if(!footprint)return 'Footprint exceeds room dimensions';if(Number(space.door)>0&&Math.min(...dims)>Number(space.door))return 'Access warning: smallest item side exceeds opening';return 'Footprint fits; check clearance, packaging and turning space';}
export function validateBoard(b){return b&&Array.isArray(b.items)&&b.items.length<=100&&b.items.every(i=>i&&typeof i.id==='string'&&typeof i.name==='string'&&i.name.length<300&&['price','delivery','assembly','width','depth','height','resale','requiredDepth'].every(k=>i[k]==null||i[k]===''||Number.isFinite(Number(i[k]))&&Number(i[k])>=0)&&(!i.contributions||Object.values(i.contributions).every(n=>Number.isFinite(Number(n))&&Number(n)>=0)))&&Array.isArray(b.people)&&b.people.length>0&&b.people.length<=12&&b.people.every(n=>typeof n==='string'&&n.length<=100&&!['__proto__','constructor','prototype'].includes(n))&&Number.isFinite(Number(b.budget))&&Number(b.budget)>=0&&Number.isFinite(Number(b.tax))&&Number(b.tax)>=0&&Number(b.tax)<=30;}

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='roomedit-board-v2';let state={items:[],people:['Me'],budget:2500,tax:0,space:{},purpose:'living',horizon:'long'};try{const saved=JSON.parse(localStorage.getItem(key));if(validateBoard(saved))state={...state,...saved};}catch{}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{status('This browser could not save your board. Export a copy.');}}
function status(t){$('#board-status').textContent=t;}
const nav=document.querySelector('.mode-tabs');nav.insertAdjacentHTML('beforeend','<button type="button" id="board-tab" aria-pressed="false">Room board &amp; move plan</button>');
const section=document.createElement('section');section.id='board-mode';section.hidden=true;document.querySelector('footer').before(section);

const lanes={
 letgo:{title:'Let go',blurb:'Sell, donate or recycle what isn’t coming with you.',add:'Add something to let go',preset:{source:'owned',decision:'sell'},empty:'Nothing here yet. Add the pieces you’d rather not move: that old couch, the wobbly shelf.'},
 keep:{title:'Bring with me',blurb:'What you own and are moving. Check it fits the new room and the door.',add:'Add something you’re keeping',preset:{source:'owned',decision:'keep'},empty:'List the furniture you’re keeping so you can check it fits through the door and into the new room.'},
 buy:{title:'Get new',blurb:'New and secondhand pieces you’re considering, against your budget.',add:'Add a new piece',preset:{source:'new',decision:'buy'},empty:'Save finds from Shop a photo or Marketplace, add a link you found, or start from a budget starter set.'}
};
const decisionLabels={keep:'Keep',sell:'Sell',donate:'Donate',dispose:'Recycle / dispose',buy:'Buy'};
const sourceLabels={owned:'Owned',new:'New',used:'Secondhand'};
const icons={sofa:'M3 12v6h18v-6M5 12V8.5A2.5 2.5 0 0 1 7.5 6h9A2.5 2.5 0 0 1 19 8.5V12M3 12a2 2 0 0 1 4 0v2h10v-2a2 2 0 0 1 4 0M6 18v2M18 18v2',chair:'M7 3.5h10V12H7zM5.5 12h13v3.5h-13zM7 15.5V21M17 15.5V21',table:'M3 9h18M6 9v11M18 9v11M4 9l2-3h12l2 3',desk:'M3 8h18M5 8v12M19 8v12M12.5 8v6H19',bed:'M3 19V6M3 14h18v5M21 19v-5M7 14v-3h5v3M12 11h7a2 2 0 0 1 2 2v1',storage:'M4 4h16v16H4zM4 12h16M10 8h4M10 16h4',rug:'M5 5h14v14H5zM8 5V3M12 5V3M16 5V3M8 21v-2M12 21v-2M16 21v-2',lamp:'M8 3h8l3.5 7h-15zM12 10v9M8 21h8',other:'M5 5h14v14H5z'};
const laneOf=i=>['sell','donate','dispose'].includes(i.decision)?'letgo':i.decision==='keep'||i.source==='owned'?'keep':'buy';
const isSpend=i=>laneOf(i)==='buy';
const unknownCost=v=>v===''||v==null;
const fitState=msg=>/^Footprint fits/.test(msg)?'ok':/exceeds|warning/i.test(msg)?'warn':'unknown';
const shortDate=d=>{if(!d)return '';const t=new Date(d+'T00:00:00Z');return Number.isNaN(+t)?esc(d):t.toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});};
const icon=c=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[c]||icons.other}"/></svg>`;
let view='all';

section.innerHTML=`<div class="rb-hero"><p class="eyebrow">MOVE-OUT · MOVE-IN · SHOPPING</p><h1>Your move, piece by piece.</h1><p class="intro">Decide what to let go, check what’s coming with you, and plan what’s new, all in one place.</p></div>
<div id="board-overview" class="rb-overview"></div>
<div class="rb-toolbar"><div class="rb-tabs" role="tablist" aria-label="Board view">${[['all','Everything'],['letgo','Let go'],['keep','Bring with me'],['buy','Get new']].map(([v,l])=>`<button type="button" role="tab" data-view="${v}" aria-selected="${v==='all'}">${l}<span class="rb-count" data-count="${v}"></span></button>`).join('')}</div>
<div class="rb-toolbar-actions"><details class="rb-menu"><summary>Share &amp; backup</summary><div class="rb-menu-list"><button type="button" id="share-board">Copy snapshot link</button><button type="button" id="export-board">Download backup (.json)</button><label class="import-label">Restore from backup<input id="import-board" type="file" accept="application/json" hidden></label></div></details><button type="button" class="rb-add" id="add-item">+ Add piece</button></div></div>
<p id="board-status" class="rb-status" role="status" aria-live="polite"></p>
<div class="board-layout"><div id="board-items" class="rb-lanes"></div>
<aside class="rb-setup" aria-labelledby="rb-setup-title"><h2 id="rb-setup-title">Your setup</h2><p class="note rb-autosave">Changes save automatically on this device.</p>
<details open><summary>Budget</summary><label>What’s the room for?<select id="purpose"><option value="living">Relaxing &amp; hosting</option><option value="work">Working from home</option><option value="sleep">Sleeping</option><option value="small">Small-space living</option></select></label><div class="rb-pair"><label>Budget $<input id="room-budget" type="number" min="0" max="1000000" inputmode="decimal"></label><label>Sales tax %<input id="tax-rate" type="number" min="0" max="30" step=".01" inputmode="decimal"></label></div><label>How long will you stay?<select id="horizon"><option value="long">Long-term home</option><option value="short">Under a year / moving often</option></select></label></details>
<details open><summary>New room &amp; access</summary><div class="rb-pair"><label>Width (in)<input id="room-width" type="number" min="1" inputmode="decimal"></label><label>Depth (in)<input id="room-depth" type="number" min="1" inputmode="decimal"></label></div><label>Narrowest door or elevator (in)<input id="room-door" type="number" min="1" inputmode="decimal"></label><label>Access notes<textarea id="access" placeholder="3rd-floor walk-up, elevator booking, tight stair turn…" maxlength="1000"></textarea></label></details>
<details><summary>Household</summary><label>Who’s deciding? (comma separated)<input id="people" maxlength="200" placeholder="Me, Sam"></label><p class="note">Add roommates or a partner to record votes and who’s chipping in on new pieces. Shared links are snapshots, not live editing.</p></details>
<details class="rb-tips"><summary>Before you buy, sell or move</summary><p>Confirm availability and condition in person and agree on pickup timing. A saved listing is not a verified seller or a booking.</p><p>Check curbside vs. in-room delivery, stair fees, elevator rules and return costs with the retailer.</p><p>Measure doors, stair turns and elevators before moving day. Book donation pickups early because they fill up near month-end.</p></details>
</aside></div>
<dialog id="item-dialog" class="rb-dialog"><form id="item-form" data-source="new"><div class="rb-dialog-head"><h2 id="item-title">Add a piece</h2><button type="button" class="rb-x" id="close-item" aria-label="Close">×</button></div>
<fieldset class="rb-source"><legend>What kind of piece?</legend>${Object.entries({owned:'Something I own',new:'New from a store',used:'Secondhand find'}).map(([v,l])=>`<label><input type="radio" name="source" value="${v}"><span>${l}</span></label>`).join('')}</fieldset>
<div class="edit-grid"><label class="wide">Name<input name="name" required maxlength="200" placeholder="e.g. Grey sectional sofa"></label><label>Category<select name="category">${['sofa','chair','table','desk','bed','storage','rug','lamp','other'].map(v=>`<option value="${v}">${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label>
<label class="only-owned">Plan for it<select name="decision"><option value="keep">Keep &amp; move it</option><option value="sell">Sell</option><option value="donate">Donate</option><option value="dispose">Recycle / dispose</option></select></label>
<label class="only-buy">Price $<input name="price" type="number" min="0" max="1000000" step=".01" inputmode="decimal"></label></div>
<h3 class="rb-group only-letgo">Letting it go</h3><div class="edit-grid only-letgo"><label class="only-sell">Expected resale $<input name="resale" type="number" min="0" max="1000000" step=".01" inputmode="decimal"></label><label>Gone by<input name="deadline" type="date"></label><label class="wide">Who keeps the money / item?<input name="ownership" maxlength="500" placeholder="Split 50/50 with Sam, or Sam buys out my half"></label></div>
<h3 class="rb-group only-buy">Cost &amp; buying</h3><div class="edit-grid only-buy"><label class="wide">Link<input name="url" type="url" placeholder="https://…"></label><label>Delivery $<input name="delivery" type="number" min="0" max="100000" step=".01" inputmode="decimal" placeholder="Unknown"></label><label>Assembly $<input name="assembly" type="number" min="0" max="100000" step=".01" inputmode="decimal" placeholder="Unknown"></label><label class="wide">Style / color notes<input name="style" maxlength="300" placeholder="Tan leather, mid-century"></label></div>
<h3 class="rb-group">Size</h3><div class="edit-grid rb-dims"><label>Width (in)<input name="width" type="number" min=".1" step=".1" inputmode="decimal"></label><label>Depth (in)<input name="depth" type="number" min=".1" step=".1" inputmode="decimal"></label><label>Height (in)<input name="height" type="number" min=".1" step=".1" inputmode="decimal"></label></div><label class="rb-check"><input name="portable" type="checkbox"> Comes apart or fits in a car (confirmed)</label>
<details class="rb-more"><summary>More details</summary><div class="edit-grid"><label class="only-buy">Delivery service / timing<input name="service" placeholder="In-room, stair fees, delivery date…" maxlength="400"></label><label class="only-buy">Assembly time / tools<input name="tools" placeholder="2 hours, screwdriver" maxlength="300"></label><label class="only-buy">Returns / payment<input name="returns" maxlength="500" placeholder="Return window, fees, payment methods"></label><label class="only-buy">Availability last checked<input name="confirmed" type="date"></label><label class="only-buy">Proposed pickup<input name="pickup" type="datetime-local"></label><label class="only-buy">Min. desk depth needed (in)<input name="requiredDepth" type="number" min=".1" step=".1"></label><label class="wide">Condition notes<input name="evidence" maxlength="500" placeholder="Receipt, maker marks, wear; your notes, not verified"></label></div></details>
<p class="note only-buy">Blank delivery or assembly costs count as unknown, not free.</p>
<div class="rb-dialog-actions"><button type="button" class="rb-btn" id="cancel-item">Cancel</button><button type="submit" class="primary">Save piece</button></div></form></dialog>`;

function switchBoard(){for(const m of ['photo','planner','board']){$('#'+m+'-mode').hidden=m!=='board';$('#'+m+'-tab').setAttribute('aria-pressed',String(m==='board'));}render();}
$('#board-tab').onclick=switchBoard;for(const m of ['photo','planner'])$('#'+m+'-tab').addEventListener('click',()=>{$('#board-mode').hidden=true;$('#board-tab').setAttribute('aria-pressed','false');});

function fillBrief(){for(const [id,value] of Object.entries({'purpose':state.purpose,'horizon':state.horizon,'room-budget':state.budget,'tax-rate':state.tax,'people':state.people.join(', '),'room-width':state.space.width||'','room-depth':state.space.depth||'','room-door':state.space.door||'','access':state.space.access||''}))$('#'+id).value=value;}
function applyBrief(e){if(e&&!e.target.reportValidity())return;if(![...section.querySelectorAll('.rb-setup input')].every(el=>el.checkValidity()))return;state.purpose=$('#purpose').value;state.horizon=$('#horizon').value;state.budget=Number($('#room-budget').value);state.tax=Number($('#tax-rate').value);state.people=[...new Set($('#people').value.split(',').map(n=>n.trim()).filter(n=>n&&n.length<=100&&!['__proto__','constructor','prototype'].includes(n)))].slice(0,12);if(!state.people.length)state.people=['Me'];state.space={width:$('#room-width').value,depth:$('#room-depth').value,door:$('#room-door').value,access:$('#access').value};persist();render();}
section.querySelector('.rb-setup').addEventListener('change',applyBrief);

let editId=null;
function syncForm(){const f=$('#item-form'),source=f.elements.source.value||'new';f.dataset.source=source;const decision=source==='owned'?f.elements.decision.value:'buy';f.dataset.decision=decision;f.dataset.lane=['sell','donate','dispose'].includes(decision)?'letgo':source==='owned'?'keep':'buy';f.elements.price.required=source!=='owned';}
function edit(item,preset){editId=item?.id||null;const f=$('#item-form');f.reset();const data=item||{...preset};for(const el of f.elements){if(!el.name||el.type==='radio')continue;if(el.type==='checkbox')el.checked=!!data[el.name];else el.value=data[el.name]??(el.tagName==='SELECT'?el.options[0].value:'');}
 const source=data.source||'new';f.querySelector(`[name=source][value="${source}"]`).checked=true;if(source==='owned'&&!['keep','sell','donate','dispose'].includes(data.decision))f.elements.decision.value='keep';
 $('#item-title').textContent=item?'Edit piece':preset?.source==='owned'?(preset.decision==='keep'?'Add something you’re keeping':'Add something to let go'):'Add a new piece';syncForm();$('#item-dialog').showModal();f.elements.name.focus();}
$('#item-form').addEventListener('change',e=>{if(['source','decision'].includes(e.target.name))syncForm();});
$('#add-item').onclick=()=>edit(null,view==='all'?lanes.buy.preset:lanes[view].preset);$('#cancel-item').onclick=$('#close-item').onclick=()=>$('#item-dialog').close();
$('#item-dialog').addEventListener('click',e=>{if(e.target.id==='item-dialog')e.target.close();});
$('#item-form').onsubmit=e=>{e.preventDefault();const f=e.target;const data=Object.fromEntries(new FormData(f));if(data.url&&!/^https?:\/\//i.test(data.url)){f.elements.url.setCustomValidity('Use an http or https link.');f.elements.url.reportValidity();f.elements.url.setCustomValidity('');return;}
 if(data.source!=='owned')data.decision='buy';else if(data.price==='')data.price='0';
 const old=state.items.find(i=>i.id===editId);const item={...old,...data,id:editId||crypto.randomUUID(),portable:f.elements.portable.checked};if(old)state.items[state.items.indexOf(old)]=item;else state.items.push(item);persist();render();$('#item-dialog').close();status(`${old?'Updated':'Added'} “${item.name}” in ${lanes[laneOf(item)].title}.`);};

function safeUrl(u){try{const url=new URL(u);return ['http:','https:'].includes(url.protocol)?url.href:'';}catch{return '';}}

function overview(){const by=l=>state.items.filter(i=>laneOf(i)===l),go=by('letgo'),keep=by('keep'),buy=by('buy');
 const spend=buy.reduce((s,i)=>s+totalCost(i,state.tax),0),pct=state.budget>0?Math.min(100,spend/state.budget*100):spend>0?100:0,over=spend>state.budget;
 const resale=go.filter(i=>i.decision==='sell').reduce((s,i)=>s+Number(i.resale||0),0);
 const next=go.map(i=>i.deadline).filter(Boolean).sort()[0];
 const warn=keep.filter(i=>fitState(fitCheck(i,state.space))==='warn').length,bulky=keep.filter(i=>!i.portable).length;
 const unknown=buy.filter(i=>unknownCost(i.delivery)||unknownCost(i.assembly)).length;
 const n=(c,w)=>`${c} ${c===1?w:w+'s'}`;
 $('#board-overview').innerHTML=`<button type="button" class="rb-stat rb-stat-letgo" data-view="letgo"><span class="rb-stat-label">Let go</span><strong>${n(go.length,'piece')}</strong><span>${resale?cash(resale)+' expected from sales':go.length?'Nothing listed for sale':'Sell, donate or recycle'}${next?` · first due ${shortDate(next)}`:''}</span></button>
 <button type="button" class="rb-stat rb-stat-keep" data-view="keep"><span class="rb-stat-label">Bring with me</span><strong>${n(keep.length,'piece')}</strong><span>${keep.length?(warn?`<b class="rb-warn-text">${n(warn,'fit warning')}</b> · `:'')+`${bulky} need${bulky===1?'s':''} a truck or helpers`:'Check fit before moving day'}</span></button>
 <button type="button" class="rb-stat rb-stat-buy" data-view="buy"><span class="rb-stat-label">Get new</span><strong>${cash(spend)} <small>of ${cash(state.budget)}</small></strong><span class="rb-meter${over?' is-over':''}" role="img" aria-label="${Math.round(spend/(state.budget||1)*100)}% of budget"><span style="width:${pct}%"></span></span><span>${over?`<b class="rb-warn-text">${cash(spend-state.budget)} over budget</b>`:cash(state.budget-spend)+' left'}${unknown?` · ${unknown} with unknown delivery/assembly`:''}</span></button>`;
 for(const l of ['all','letgo','keep','buy'])section.querySelector(`[data-count="${l}"]`).textContent=l==='all'?state.items.length||'':by(l).length||'';}

function card(i){const lane=laneOf(i),fit=fitCheck(i,state.space),fs=fitState(fit),total=totalCost(i,state.tax),multi=state.people.length>1,id=esc(i.id);
 const dims=[i.width,i.depth,i.height].every(v=>Number(v)>0)?`${esc(i.width)}″ W × ${esc(i.depth)}″ D × ${esc(i.height)}″ H`:'Size not added';
 const fitChip=`<span class="rb-chip rb-fit-${fs}" title="${esc(fit)}">${fs==='ok'?'✓ Fits':fs==='warn'?'⚠ '+(/Access/.test(fit)?'Door check':'Too big'):'Fit unknown'}</span>`;
 const votes=Object.entries(i.votes||{}).filter(([p,v])=>state.people.includes(p)&&v!=='Undecided');const yes=votes.filter(([,v])=>v==='Yes').length;
 let detail='',side='';
 if(lane==='letgo'){side=i.decision==='sell'?`<strong class="rb-amount">${cash(Number(i.resale||0))}</strong><span class="rb-sub">expected</span>`:'';
  detail=`<p class="rb-line">${i.deadline?`Gone by <b>${shortDate(i.deadline)}</b>`:'No deadline set'}${i.ownership?' · '+esc(i.ownership):''}</p>`;}
 else if(lane==='keep'){detail=`<p class="rb-line">${dims} · ${i.portable?'Comes apart / car-friendly':'Needs a truck or helpers'}</p>${fs==='warn'?`<p class="rb-alert">${esc(fit)}</p>`:''}`;}
 else{side=`<strong class="rb-amount">${cash(total)}</strong><span class="rb-sub">est. total</span>`;
  detail=`<p class="rb-line">${cash(Number(i.price||0))} + ${cash(Number(i.price||0)*state.tax/100)} tax · delivery ${unknownCost(i.delivery)?'<em>unknown</em>':cash(Number(i.delivery))} · assembly ${unknownCost(i.assembly)?'<em>unknown</em>':cash(Number(i.assembly))}</p>${fs==='warn'?`<p class="rb-alert">${esc(fit)}</p>`:''}${Number(i.requiredDepth)>0?`<p class="rb-line">Desk depth: ${!Number(i.depth)?'unknown':Number(i.depth)>=Number(i.requiredDepth)?'meets your minimum':'<b class="rb-warn-text">too shallow for your need</b>'}</p>`:''}`;}
 const contributed=Object.entries(i.contributions||{}).filter(([p])=>state.people.includes(p)).reduce((s,[,n])=>s+Number(n||0),0);
 const household=lane==='buy'&&multi?`<details class="rb-household"><summary>Household · ${votes.length}/${state.people.length} voted${votes.length?`, ${yes} yes`:''}${contributed?` · ${cash(contributed)} pledged`:''}</summary><div class="household">${state.people.map((name,index)=>`<div class="rb-person"><span>${esc(name)}</span><select aria-label="${esc(name)}’s vote on ${esc(i.name)}" data-vote="${id}" data-person="${index}">${['Undecided','Yes','Maybe','No'].map(v=>`<option ${i.votes?.[name]===v?'selected':''}>${v}</option>`).join('')}</select><input aria-label="${esc(name)} contribution for ${esc(i.name)}" placeholder="$ chipping in" type="number" min="0" step=".01" data-contribution="${id}" data-person="${index}" value="${esc(i.contributions?.[name]||'')}"></div>`).join('')}</div><p class="note">${contributed>total?'Overfunded by '+cash(contributed-total):cash(Math.max(0,total-contributed))+' still unfunded'}. Records only; no payments are processed.</p></details>`:'';
 const facts=[['Size',dims],['Fit',esc(fit)],...(lane==='buy'?[['Delivery',esc(i.service||'Not checked')],['Assembly',esc(i.tools||'Not checked')],['Returns',esc(i.returns||'Not checked')],['Availability',i.confirmed?'Checked '+shortDate(i.confirmed):'Not confirmed'],['Pickup',esc(i.pickup||'Not arranged')]]:[]),['Condition',esc(i.evidence||'No notes')],...(lane!=='buy'&&i.ownership?[['Ownership',esc(i.ownership)]]:[])];
 const decide=i.source==='owned'?`<label class="rb-decide"><span class="visually-hidden">Plan for ${esc(i.name)}</span><select data-decision="${id}">${['keep','sell','donate','dispose'].map(d=>`<option value="${d}" ${i.decision===d||(d==='keep'&&lane==='keep')?'selected':''}>${decisionLabels[d]}</option>`).join('')}</select></label>`:'';
 return `<article class="rb-item rb-item-${lane}"><div class="rb-icon">${icon(i.category)}</div><div class="rb-main"><div class="rb-head"><h3>${esc(i.name)}</h3><div class="rb-side">${side}</div></div>
 <div class="rb-chips"><span class="rb-chip">${sourceLabels[i.source]||'New'}</span>${lane==='letgo'?`<span class="rb-chip rb-chip-${esc(i.decision)}">${decisionLabels[i.decision]}</span>`:''}${lane!=='letgo'?fitChip:''}${i.portable?'<span class="rb-chip">Portable</span>':''}${i.style&&lane==='buy'?`<span class="rb-style">${esc(i.style)}</span>`:''}</div>
 ${detail}${household}
 <div class="rb-actions">${decide}<details class="rb-facts"><summary>Details</summary><dl>${facts.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></details>${safeUrl(i.url)?`<a href="${esc(safeUrl(i.url))}" target="_blank" rel="noopener noreferrer">Open listing ↗</a>`:''}<button type="button" data-edit="${id}">Edit</button><button type="button" class="rb-remove" data-delete="${id}" aria-label="Remove ${esc(i.name)}">Remove</button></div></div></article>`;}

function render(){overview();for(const b of section.querySelectorAll('.rb-tabs [data-view]'))b.setAttribute('aria-selected',String(b.dataset.view===view));
 const order=view==='all'?['letgo','keep','buy']:[view];
 $('#board-items').innerHTML=!state.items.length&&view==='all'?`<div class="rb-start"><h2>Start with what you have.</h2><p>Moving, downsizing or refreshing a room? Sort each piece into one of three piles:</p><div class="rb-start-grid">${Object.entries(lanes).map(([l,x])=>`<button type="button" class="rb-start-card rb-stat-${l}" data-add="${l}"><strong>${x.title}</strong><span>${x.blurb}</span><b>${x.add} →</b></button>`).join('')}</div></div>`:
 order.map(l=>{let items=state.items.filter(i=>laneOf(i)===l);if(state.horizon==='short'&&l!=='letgo')items=[...items].sort((a,b)=>Number(b.portable)-Number(a.portable));const x=lanes[l];
  return `<section class="rb-lane rb-lane-${l}" aria-labelledby="lane-${l}"><div class="rb-lane-head"><div><h2 id="lane-${l}">${x.title} <span>${items.length||''}</span></h2><p>${x.blurb}</p></div><div class="rb-lane-actions">${l==='buy'?'<button type="button" class="rb-btn" id="starter">Budget starter set</button>':''}<button type="button" class="rb-btn" data-add="${l}">+ Add</button></div></div>${items.length?items.map(card).join(''):`<p class="rb-empty">${x.empty}</p>`}</section>`;}).join('');}

section.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!section.contains(b))return;
 if(b.dataset.view){view=b.dataset.view;render();if(b.classList.contains('rb-stat'))$('#board-items').scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(b.dataset.add)return edit(null,lanes[b.dataset.add].preset);
 if(b.id==='starter')return starter();
 if(b.dataset.edit)return edit(state.items.find(i=>i.id===b.dataset.edit));
 if(b.dataset.delete){const item=state.items.find(i=>i.id===b.dataset.delete);if(!item)return;state.items=state.items.filter(i=>i!==item);persist();render();status(`Removed “${item.name}”.`);}});
$('#board-items').addEventListener('change',e=>{const el=e.target;
 if(el.dataset.decision){const item=state.items.find(i=>i.id===el.dataset.decision);if(!item)return;item.decision=el.value;persist();render();status(`“${item.name}” moved to ${lanes[laneOf(item)].title}.`);return;}
 const id=el.dataset.vote||el.dataset.contribution;if(!id)return;const item=state.items.find(i=>i.id===id),person=state.people[Number(el.dataset.person)];if(!item||!person||!el.reportValidity())return;if(el.dataset.vote){item.votes??={};item.votes[person]=el.value;}else{item.contributions??={};item.contributions[person]=Number(el.value);}persist();const open=el.closest('details')?.open;render();if(open)section.querySelector(`[data-vote="${CSS.escape(id)}"]`)?.closest('details')?.setAttribute('open','');});

function saveProduct(p){if(state.items.some(i=>i.catalogId===p.id)){status('That piece is already on your board.');return false;}state.items.push({id:crypto.randomUUID(),catalogId:p.id,name:p.name+' '+p.type,price:p.price,url:p.url,style:p.detail,category:p.category,source:'new',decision:'buy',delivery:'',assembly:''});persist();render();return true;}
window.addEventListener('roomedit-save',e=>{const p=catalog.find(p=>p.id===e.detail);if(p&&saveProduct(p))status('Saved '+p.name+' to Get new on your room board.');});
function starter(){const groups={living:['sofa','table','lamp'],work:['desk','chair','lamp'],sleep:['bed','table','lamp'],small:['chair','storage','lamp']}[state.purpose];let remaining=Math.max(0,state.budget-state.items.filter(isSpend).reduce((s,i)=>s+totalCost(i,state.tax),0));let count=0;for(const cat of groups){if(state.items.some(i=>i.category===cat&&laneOf(i)!=='letgo'))continue;const p=catalog.filter(p=>p.category===cat&&!state.items.some(i=>i.catalogId===p.id)).sort((a,b)=>a.price-b.price)[0];if(p&&p.price*(1+state.tax/100)<=remaining){saveProduct(p);remaining-=p.price*(1+state.tax/100);count++;}}status(count?`Added ${count} low-cost starter ${count===1?'piece':'pieces'}, skipping categories you already own or plan to buy. Check delivery and assembly costs.`:'No starter pieces fit your remaining budget, or you already have every category covered.');}
$('#export-board').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='roomedit-board.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);section.querySelector('.rb-menu').open=false;status('Backup downloaded.');};
function importBoard(b){if(!validateBoard(b))throw Error();state={...state,...b,space:b.space||{}};persist();fillBrief();render();switchBoard();}
$('#import-board').onchange=async e=>{section.querySelector('.rb-menu').open=false;try{const file=e.target.files[0];if(!file||file.size>500000)throw Error();const b=JSON.parse(await file.text());if(state.items.length&&!confirm('Replace your current board with this backup?'))return;importBoard(b);status('Board restored from backup.');}catch{status('Could not restore this file. Choose a Room Edit .json backup under 500 KB.');}e.target.value='';};
$('#share-board').onclick=async()=>{section.querySelector('.rb-menu').open=false;const data=btoa(unescape(encodeURIComponent(JSON.stringify(state))));if(data.length>16000){status('This board is too large for a link. Download a backup instead.');return;}const url=location.origin+location.pathname+'#board='+data;try{await navigator.clipboard.writeText(url);status('Snapshot link copied. It includes names, contributions and notes; changes won’t sync.');}catch{status('Clipboard unavailable. Download a backup to share instead.');}};
fillBrief();render();if(location.hash.startsWith('#board=')){try{const b=JSON.parse(decodeURIComponent(escape(atob(location.hash.slice(7)))));if(validateBoard(b)&&confirm('Load the shared board snapshot? This replaces your local board.'))importBoard(b);}catch{status('The shared board link could not be read.');}history.replaceState(null,'',location.pathname);}

window.addEventListener('roomedit-market-save',e=>{const p=e.detail;if(state.items.some(i=>i.marketId===p.id)){status('This marketplace piece is already on your board.');return;}state.items.push({id:crypto.randomUUID(),marketId:p.id,name:p.name+' (demo listing)',price:p.price,source:'used',decision:'buy',category:p.category,width:p.width,depth:p.depth,height:p.height,portable:p.portable,delivery:'',assembly:'',evidence:p.condition+' · Demo seller: '+p.seller+' · Not verified',service:p.platform+' · '+p.area+' · Pickup preference: '+(p.pickupPreference||'not selected')+' (not booked)',style:'Marketplace demo'});persist();render();status('Marketplace piece saved to Get new. Pickup is a preference, not a booking.');});
